package br.com.onda;
import java.net.*;import java.util.*;import org.json.*;
/** Wikimedia Commons bitmap search; displays source, author and license with every image. */
final class ImageCatalog {
 static final class Photo {final String title,thumb,page,credit,license,mime;Photo(String title,String thumb,String page,String credit,String license,String mime){this.title=title;this.thumb=thumb;this.page=page;this.credit=credit;this.license=license;this.mime=mime;}String attribution(){return title+"\n"+credit+" • "+license+"\n"+page;}}
 static String endpoint(String query,int offset){String q=query==null?"":query.trim();if(q.isEmpty()||q.length()>120)throw new IllegalArgumentException("Digite até 120 caracteres para buscar fotos.");try{return "https://commons.wikimedia.org/w/api.php?action=query&format=json&formatversion=2&generator=search&gsrnamespace=6&gsrlimit=20&gsroffset="+Math.max(0,offset)+"&gsrsearch="+URLEncoder.encode(q+" filetype:bitmap","UTF-8")+"&prop=imageinfo&iiprop=url%7Cmime%7Cextmetadata&iiurlwidth=1024";}catch(Exception e){throw new IllegalArgumentException(e);}}
 static String mediaUrl(String raw){return url(raw,"upload.wikimedia.org");}static String pageUrl(String raw){return url(raw,"commons.wikimedia.org");}
 private static String url(String raw,String host){try{URI u=new URI(raw);if(!"https".equalsIgnoreCase(u.getScheme())||!host.equalsIgnoreCase(u.getHost())||u.getUserInfo()!=null||u.getFragment()!=null||u.getPort()!=-1&&u.getPort()!=443)throw new Exception();return u.toASCIIString();}catch(Exception e){throw new IllegalArgumentException("Endereço da imagem inválido.");}}
 static List<Photo> parse(String raw)throws JSONException{JSONObject root=new JSONObject(raw);if(root.has("error"))throw new JSONException("A fonte de imagens não respondeu à busca.");JSONObject query=root.optJSONObject("query");JSONArray pages=query==null?null:query.optJSONArray("pages");ArrayList<JSONObject> ranked=new ArrayList<>();if(pages!=null)for(int i=0;i<pages.length();i++)ranked.add(pages.getJSONObject(i));ranked.sort(Comparator.comparingInt(p->p.optInt("index",Integer.MAX_VALUE)));ArrayList<Photo> out=new ArrayList<>();Set<String> seen=new HashSet<>();for(JSONObject page:ranked)try{JSONArray info=page.getJSONArray("imageinfo");JSONObject data=info.getJSONObject(0);String mime=data.optString("thumbmime",data.optString("mime"));if(!Arrays.asList("image/jpeg","image/png","image/webp").contains(mime))continue;String thumb=mediaUrl(data.getString("thumburl")),source=pageUrl(data.getString("descriptionurl"));JSONObject ext=data.optJSONObject("extmetadata");String title=clean(page.optString("title").replaceFirst("^File:",""),160),credit=meta(ext,"Artist"),license=meta(ext,"LicenseShortName");if(license.isEmpty())continue;if(credit.isEmpty())credit="Autor: consulte a fonte";if(seen.add(source))out.add(new Photo(title,thumb,source,credit,license,mime));}catch(JSONException|IllegalArgumentException ignored){}return out;}
 private static String meta(JSONObject ext,String key){JSONObject o=ext==null?null:ext.optJSONObject(key);return clean(o==null?"":o.optString("value"),240);}
 static String clean(String value,int max){String s=value==null?"":value.replaceAll("<[^>]*>"," ").replace("&amp;","&").replace("&quot;","\"").replace("&#39;","'").replace("&lt;","<").replace("&gt;",">").replaceAll("\\s+"," ").trim();return s.substring(0,Math.min(max,s.length()));}
}
